const out = {};
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.key !== undefined && String(j.key).trim() !== '') {
    out[String(j.key).trim()] = String(j.value === undefined ? '' : j.value).trim();
  }
}
return [{ json: out }];

const rows = $('Read Leads A').all().map(i => i.json).filter(Boolean);
const s = $('Settings Map A').first().json;
const today = new Date().toISOString().slice(0, 10);
const st = (r) => String(r.outreach_status === undefined ? 'new' : r.outreach_status || 'new').toLowerCase();
const fresh = rows.filter(r => st(r) === 'new' && String(r.site_url || ''));
const phoneOnly = rows.filter(r => st(r) === 'new' && String(r.site_url || '') && !String(r.email || ''));
const due = rows.filter(r => st(r) === 'sent' && String(r.next_touch || '') && String(r.next_touch) <= today && (parseInt(String(r.sent_count || '0'), 10) || 0) < 3);
const replied = rows.filter(r => st(r) === 'replied');
const errors = rows.filter(r => String(r.website_status || '').toLowerCase() === 'deploy_error' || String(r.gen_status || '').toLowerCase() === 'needs_rewrite');
const won = rows.filter(r => st(r) === 'won');
const dead = rows.filter(r => st(r) === 'dead');
const lines = [];
lines.push('MORNING REPORT - ' + today + ' - ' + rows.length + ' leads total.');
if (fresh.length) lines.push('New, ready to email: ' + fresh.length + (fresh.length > 6 ? ' (first 6: ' + fresh.slice(0, 6).map(r => r.business_name).join(', ') + ')' : ' - ' + fresh.map(r => r.business_name).join(', ')));
if (phoneOnly.length) lines.push('No email, need a text/call: ' + phoneOnly.map(r => r.business_name).join(', '));
if (due.length) lines.push('Follow-ups due today: ' + due.map(r => '#' + r.id + ' ' + r.business_name).join(', '));
if (replied.length) lines.push('REPLIES waiting on you: ' + replied.map(r => '#' + r.id + ' ' + r.business_name).join(', '));
if (errors.length) lines.push('Problem rows: ' + errors.map(r => '#' + r.id + ' ' + r.business_name + ' (' + (r.website_status || r.gen_status) + ')').join(', '));
lines.push('Won: ' + won.length + ' | Dead: ' + dead.length + ' | Collected target: $2,350');
lines.push('Autosend: ' + (String(s.autosend || 'on') === 'off' ? 'OFF - drafts come here at 9:11' : 'ON - up to ' + (s.daily_cap || 10) + ' emails go out at 9:11'));
return [{ json: { text: lines.join('\n') } }];

const out = {};
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.key !== undefined && String(j.key).trim() !== '') {
    out[String(j.key).trim()] = String(j.value === undefined ? '' : j.value).trim();
  }
}
return [{ json: out }];

const s = $('Settings Map B').first().json;
const cap = parseInt(String(s.daily_cap || '10'), 10) || 10;
const today = new Date();
const iso = today.toISOString().slice(0, 10);
const plusDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x.toISOString().slice(0, 10); };
const rows = $input.all().map(i => i.json).filter(Boolean);
const st = (r) => String(r.outreach_status === undefined ? 'new' : r.outreach_status || 'new').toLowerCase();
const followups = rows.filter(r => st(r) === 'sent' && String(r.next_touch || '') && String(r.next_touch) <= iso && (parseInt(String(r.sent_count || '0'), 10) || 0) < 3 && String(r.email || ''));
const fresh = rows.filter(r => st(r) === 'new' && String(r.site_url || '') && String(r.email || ''));
const batch = [];
for (const r of followups) { if (batch.length >= cap) break; batch.push(r); }
for (const r of fresh) { if (batch.length >= cap) break; batch.push(r); }
const out = batch.map(r => {
  const sentCount = parseInt(String(r.sent_count || '0'), 10) || 0;
  const isF = sentCount > 0 && st(r) === 'sent';
  const price = String(r.price_quoted || s.price_default || '$500');
  const body = 'Hi ' + String(r.business_name || 'there') + ',\n\n' +
    'I run Charm City Sites, a one-person web shop here in Baltimore. I build simple sites for home-service businesses and only get paid if you like what you see.\n\n' +
    'So I went ahead and built one for ' + String(r.business_name || 'your shop') + ':\n' +
    String(r.site_url || '') + '\n\n' +
    'It loads fast on a phone (that is where your customers are), every button pushes people to call you, and Google can actually read it.\n\n' +
    (isF ? 'Just floating it back to the top of your inbox in case it got buried. ' : '') +
    'If you like it, it is yours for ' + price + ' and takes a day to put in your name. If not, no hard feelings - you keep the ideas.\n\n' +
    'Reply or call me at ' + String(s.operator_phone || '') + '.\n\n' +
    '- ' + String(s.operator_name || 'Charm City Sites') + '\nCharm City Sites, Baltimore';
  return { json: {
    id: String(r.id === undefined ? '' : r.id),
    to: String(r.email || ''),
    name: String(r.business_name || ''),
    neighborhood: String(r.neighborhood || ''),
    site_url: String(r.site_url || ''),
    price: price,
    type: isF ? 'followup' : 'new',
    subject: 'A website for ' + String(r.business_name || 'your shop') + ' (already built)',
    body: body,
    today: iso,
    sent_count_new: String(sentCount + 1),
    next_touch: sentCount + 1 >= 3 ? '' : plusDays(today, sentCount === 0 ? 3 : 7)
  } };
});
return out;

const r = $json;
const s = $('Settings Map B').first().json;
const system = 'You write short, warm, plain-text cold emails for a one-person Baltimore web shop selling an already-built demo website to a home-service business owner. Max 130 words. Plain words, no hype, no exclamation marks, no emojis, no markdown. End with the signoff line given to you. Never use placeholders like [Name]. Keep the demo URL exactly as given, on its own line.';
const user = 'Rewrite this email to be warmer and more specific (mention their neighborhood if known). Facts:
' +
  'business: ' + r.name + '
neighborhood: ' + (r.neighborhood || 'Baltimore') + '
demo_url: ' + r.site_url + '
price: ' + r.price + '
' +
  'operator_name: ' + (s.operator_name || 'Charm City Sites') + '
operator_phone: ' + (s.operator_phone || '') + '
touch_type: ' + r.type + '

CURRENT DRAFT:
' + r.body;
const b64 = Buffer.from(JSON.stringify({ system: system, user: user, max_tokens: 700 })).toString('base64');
return [{ json: { cmd: 'echo ' + b64 + ' | base64 -d | python3 "__DIR__/scripts/askbrain.py" --stdin', draft: r } }];

const prev = $('Build Brain Command').item.json.draft;
let body = prev.body;
let source = 'template';
try {
  const out = JSON.parse(String($json.stdout || '').trim().split('\n').pop());
  if (out && out.ok && out.text && String(out.text).trim().length > 40) {
    body = String(out.text).trim();
    source = out.source || 'llm';
  }
} catch (e) {}
return [{ json: Object.assign({}, prev, { body: body, copy_source: source }) }];

